begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('event-stage2-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','event-stage2-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','event-stage2-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
set local role authenticated;
select pg_temp.actor('owner');
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('account'),'kind','account','name','Banco fictício'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('income'),'kind','category','name','Receita fictícia','direction','income'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('expense'),'kind','category','name','Taxa fictícia','direction','expense'));
select public.finance_digital(pg_temp.fi('org'),pg_temp.fi('a'),'purpose',jsonb_build_object('id',pg_temp.fi('purpose'),'version',0,'name','Oferta fictícia','origin','event','account',pg_temp.fi('account'),'category',pg_temp.fi('income'),'feeCategory',pg_temp.fi('expense'),'refundCategory',pg_temp.fi('expense'),'creditCategory',pg_temp.fi('income'),'active',true));
reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured) values(pg_temp.fi('receiver'),pg_temp.fi('org'),pg_temp.fi('a'),'mercado_pago','production','configured','123','Conta fictícia',true,array[pg_temp.fi('a')],pg_temp.fi('account'),pg_temp.fi('owner'),now()+interval '1 day',array['pix'],true,true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_payment_publish(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('purpose'),pg_temp.fi('receiver'),true)$$,'publica finalidade com destino válido');

reset role;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status) values(pg_temp.fi('event2'),pg_temp.fi('org'),pg_temp.fi('a'),'Tickets fictícios etapa 2','event',now()+interval '2 days',now()+interval '3 days',10,'published');
create function pg_temp.v() returns integer language sql security definer set search_path='' as $$select version from private.church_app_events where id=pg_temp.fi('event2')$$;
create function pg_temp.admin2(a text,i uuid default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_ticket_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,i,pg_temp.v(),d)$$;
create function pg_temp.settings2() returns jsonb language sql as $$select jsonb_build_object('enabled',true,'allow_guests',true,'show_remaining',true,'purpose',pg_temp.fi('purpose'),'receiving_unit',pg_temp.fi('a'),'reservation_hours',24,'questions','[]'::jsonb)$$;
create function pg_temp.type2(n text,mode text,price integer,quantity integer) returns jsonb language sql as $$select jsonb_build_object('name',n,'mode',mode,'price',price::text,'quantity',quantity::text,'starts',now()-interval '1 day','ends',now()+interval '1 day','active',true,'per_user','2','per_cpf','','audience','public','audience_units','[]'::jsonb,'position',0)$$;
create function pg_temp.payload2(t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select jsonb_build_object('buyerName','Pessoa fictícia','buyerEmail',buyer||'-family@example.invalid','emailConfirmation',buyer||'-family@example.invalid','coupon','','intent',intent,'items',jsonb_build_array(jsonb_build_object('type',pg_temp.fi(t),'name','Participante fictício','email','','cpf','','phone','','answers','{}'::jsonb)))$$;
create function pg_temp.buy2(id text,t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi(id),case when buyer='guest' then null else pg_temp.fi(buyer) end,repeat('a',64),pg_temp.payload2(t,buyer,intent),repeat('f',64))$$;

select pg_temp.actor('owner');
set local role authenticated;
select lives_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"mercado_pago","environment":"production","version":1,"primary":true}')$$,'responsável define principal');
reset role;
select ok((select is_primary from private.finance_receivers where id=pg_temp.fi('receiver')),'principal persistida');
select is((select count(*)::integer from private.finance_receiver_events where receiver_id=pg_temp.fi('receiver') and action='primary'),1,'alteração auditada');
select is((select count(*)::integer from private.finance_digital_orders where organization_id=pg_temp.fi('org')),0,'preferência não cria pagamento');
set local role authenticated;
select throws_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"mercado_pago","environment":"production","version":1,"primary":false}')$$,'40001',null,'versão obsoleta rejeitada');
select pg_temp.actor('member');
select throws_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"mercado_pago","environment":"production","version":2,"primary":false}')$$,'42501',null,'membro não altera principal');
select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"payment_methods":["pix"]}')$$,'evento seleciona Pix habilitado');
select throws_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"payment_methods":["card"]}')$$,'22023',null,'evento não libera cartão não habilitado');
select throws_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"payment_methods":[]}')$$,'22023',null,'seleção vazia rejeitada');
select throws_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"payment_methods":["pix","pix"]}')$$,'22023',null,'duplicatas rejeitadas');
select lives_ok($$select pg_temp.admin2('type',pg_temp.fi('reserve'),pg_temp.type2('Reserva fictícia','reservation',2500,4))$$,'tipo de reserva criado');
reset role;
select lives_ok($$select pg_temp.buy2('snapshot','reserve','member','reserve')$$,'reserva salva métodos');
select is((select payment_methods from private.event_ticket_orders where id=pg_temp.fi('snapshot')),array['pix'],'pedido preserva seleção');
update private.finance_receivers set methods=array['pix','card'] where id=pg_temp.fi('receiver');
select ok(not(select is_primary from private.finance_receivers where id=pg_temp.fi('receiver')),'alterar métodos suspende preferência até reativação');
update private.finance_receivers set payments_enabled=true where id=pg_temp.fi('receiver');
set local role authenticated;
select lives_ok($$select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"payment_methods":["card"]}')$$,'evento pode alterar seleção para novos pedidos');
reset role;
select is((select payment_methods from private.event_ticket_orders where id=pg_temp.fi('snapshot')),array['pix'],'alteração não amplia pedido anterior');
select lives_ok($$select public.event_ticket_checkout(pg_temp.fi('event2'),'pay',pg_temp.fi('snapshot'),pg_temp.fi('member'),repeat('a',64))$$,'reserva antiga continua com destino original');
select is(public.event_ticket_delivery(pg_temp.fi('snapshot'),'claim')->'methods','["pix"]'::jsonb,'entrega fornece snapshot confiável');
select ok(not(select is_primary from private.finance_receivers where id=pg_temp.fi('receiver')),'seleção do evento não define principal automaticamente');
update private.finance_receivers set status='revoked' where id=pg_temp.fi('receiver');
select ok(not(select is_primary from private.finance_receivers where id=pg_temp.fi('receiver')),'revogação remove principal');
set local role authenticated;
select throws_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"mercado_pago","environment":"production","version":2,"primary":true}')$$,'22023',null,'conta revogada não pode ser principal');
reset role;
select ok(not has_table_privilege('authenticated','private.finance_receivers','update'),'sem escrita direta na conta');
select ok(not has_table_privilege('anon','private.event_ticket_orders','select'),'visitante não lê snapshot de outro pedido');

reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured)
 select pg_temp.fi('receiver2'),organization_id,unit_id,'asaas',environment,'configured','Segunda conta fictícia',true,beneficiary_units,account_id,created_by,now()+interval '1 day',methods,true,true from private.finance_receivers where id=pg_temp.fi('receiver');
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured)
 select pg_temp.fi('receiver3'),organization_id,unit_id,'safe2pay',environment,'configured','Terceira conta fictícia',true,beneficiary_units,account_id,created_by,now()+interval '1 day',methods,true,true from private.finance_receivers where id=pg_temp.fi('receiver');
set local role authenticated;
select lives_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"asaas","environment":"production","version":1,"primary":true}')$$,'seleciona segunda conta');
select lives_ok($$select public.finance_receiver_settings(pg_temp.fi('org'),pg_temp.fi('a'),'primary','{"provider":"safe2pay","environment":"production","version":1,"primary":true}')$$,'troca principal atomicamente');
reset role;
select is((select count(*)::integer from private.finance_receivers where organization_id=pg_temp.fi('org') and unit_id=pg_temp.fi('a') and environment='production' and is_primary),1,'apenas uma principal na igreja e ambiente');
select ok(not(select is_primary from private.finance_receivers where id=pg_temp.fi('receiver2')),'anterior foi desmarcada');
select throws_ok($$update private.finance_receivers set is_primary=true where id=pg_temp.fi('receiver2')$$,'23505',null,'índice protege contra duas principais mesmo fora da aplicação');
select is((select receiver_id from private.event_ticket_orders where id=pg_temp.fi('snapshot')),pg_temp.fi('receiver'),'trocar principal não redireciona pedido existente');
select * from finish();
rollback;
